SELECT Имена_станций.NAME, Доп_угли2012.YEAR, Доп_угли2012.NUMB1120, Доп_угли2012.nazar, Доп_угли2012.ibor, Доп_угли2012.berez, Доп_угли2012.per, Доп_угли2012.irbei, Доп_угли2012.kansk, Доп_угли2012.gusin, Доп_угли2012.tugn, Доп_угли2012.okino, Доп_угли2012.azey, Доп_угли2012.mug, Доп_угли2012.cher, Доп_угли2012.jer, Доп_угли2012.karab, Доп_угли2012.vork, Доп_угли2012.intin, Доп_угли2012.sver, Доп_угли2012.chel, Доп_угли2012.kizel, Доп_угли2012.urt, Доп_угли2012.tataur, Доп_угли2012.tarbag, Доп_угли2012.zab_kam, Доп_угли2012.rai, Доп_угли2012.erk, Доп_угли2012.bikin, Доп_угли2012.razdol, Доп_угли2012.hankai, Доп_угли2012.neru, Доп_угли2012.zyryan, Доп_угли2012.pyak, Доп_угли2012.gazpp, Доп_угли2012.kuzngd, Доп_угли2012.kuznt, Доп_угли2012.kuznss, Доп_угли2012.kuznun, Доп_угли2012.ekib, Доп_угли2012.maikub, Доп_угли2012.bering, Доп_угли2012.anad
FROM Имена_станций INNER JOIN (Доп_угли2012 LEFT JOIN [Поиск повторений для Доп_угли2012] ON Доп_угли2012.NUMB1120 = [Поиск повторений для Доп_угли2012].NUMB1120) ON Имена_станций.NUMB = Доп_угли2012.NUMB1120
WHERE ((([Поиск повторений для Доп_угли2012].NUMB1120) Is Null));
